settings.custom_css:
/* Static UI stays editable in native Elementor widgets. */
selector {
  background: var(--arc-brand-navy, #082465);
  color: #FFFFFF;
}
selector .elementor-widget { margin-bottom: 0; }
selector .elementor-widget-wrap { flex-direction: column; align-content: center; gap: 20px; }
selector .arc-archive-eyebrow .elementor-heading-title { color: var(--arc-brand-orange, #F48C06); }
selector .arc-archive-hero-title .elementor-heading-title { color: #FFFFFF; }
selector .arc-archive-hero-copy { max-width: 680px; margin-inline: auto; color: #FFFFFF; }
selector .elementor-text-editor p, selector .elementor-widget-text-editor p { margin: 0; }
selector .arc-archive-breadcrumbs .elementor-icon-list-items { justify-content: center; gap: 14px; }
selector .arc-archive-breadcrumbs .elementor-icon-list-text { color: #FFFFFF; }
selector .arc-archive-breadcrumbs .elementor-icon-list-icon i { color: var(--arc-brand-orange, #F48C06); }
selector .arc-archive-breadcrumbs .elementor-icon-list-icon svg { fill: var(--arc-brand-orange, #F48C06); }
selector .arc-archive-breadcrumbs a:hover .elementor-icon-list-text { color: var(--arc-brand-orange, #F48C06); }
selector .elementor-divider-separator { border-color: var(--arc-brand-orange, #F48C06); }
selector a:focus-visible { outline: 2px solid var(--arc-brand-orange, #F48C06); outline-offset: 5px; }

/* Search submission and date/guest handling remain owned by [arc_search]. */
selector {
  background: var(--arc-brand-tint, #F0F8FB);
  z-index: 40;
  overflow: visible;
  border-bottom: 1px solid rgba(var(--arc-brand-navy-rgb, 8, 36, 101), .08);
}
selector.elementor-sticky--active { box-shadow: 0 8px 24px rgba(var(--arc-brand-navy-rgb, 8, 36, 101), .08); }
selector .arc-archive-search-card > .elementor-widget-wrap {
  flex-direction: column;
  gap: 10px;
  padding: 24px;
  background: #FFFFFF;
  border: 1px solid rgba(var(--arc-brand-teal-rgb, 10, 116, 166), .15);
  border-top: 3px solid var(--arc-brand-cyan, #1B9EC2);
  border-radius: 12px;
  box-shadow: 0 6px 24px rgba(var(--arc-brand-navy-rgb, 8, 36, 101), .06);
}
selector .elementor-widget { margin-bottom: 0; }
selector .arc-archive-search-title .elementor-heading-title { color: var(--arc-brand-navy, #082465); }
selector .arc-archive-search-copy { color: var(--arc-brand-teal, #0A74A6); }
selector .elementor-widget-text-editor p { margin: 0; }
selector .arc-archive-search-shortcode { margin-top: 6px; }
selector .arc-search-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1.2fr)) repeat(2, minmax(0, .7fr)) minmax(180px, 1fr);
  gap: 16px;
  align-items: end;
  width: 100%;
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
}
selector .arc-search-field { display: flex; flex-direction: column; gap: 7px; min-width: 0; width: auto; margin: 0; padding: 0; }
selector .arc-search-field label { margin: 0; color: var(--arc-brand-navy, #082465); font-family: Inter, Arial, sans-serif; font-size: 12px; font-weight: 600; line-height: 1.5; }
selector .arc-search-field input, selector .arc-search-field select {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  min-height: 48px;
  margin: 0;
  padding: 10px 12px;
  border: 1px solid rgba(var(--arc-brand-teal-rgb, 10, 116, 166), .35);
  border-radius: 6px;
  background: #FFFFFF;
  color: var(--arc-brand-navy, #082465);
  font-family: Inter, Arial, sans-serif;
  font-size: 14px;
  line-height: 1.5;
  color-scheme: light;
}
selector .arc-search-submit {
  width: 100%;
  min-height: 48px;
  padding: 12px 16px;
  border: 1px solid var(--arc-brand-orange, #F48C06);
  border-radius: 6px;
  background: var(--arc-brand-orange, #F48C06);
  color: var(--arc-brand-navy, #082465);
  font-family: Inter, Arial, sans-serif;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.5;
  white-space: normal;
  cursor: pointer;
  box-shadow: none;
}
selector .arc-search-submit:hover { border-color: var(--arc-brand-orange-hover, #D97706); background: var(--arc-brand-orange-hover, #D97706); color: var(--arc-brand-navy, #082465); }
selector input:focus-visible, selector select:focus-visible, selector button:focus-visible { outline: 2px solid var(--arc-brand-teal, #0A74A6); outline-offset: 3px; }
@media (max-width: 1024px) {
  selector .arc-search-form { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
  selector .arc-field-submit { grid-column: 1 / -1; }
  selector .arc-archive-search-card > .elementor-widget-wrap { padding: 20px; }
}
@media (max-width: 767px) {
  selector .arc-search-form { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  selector .arc-archive-search-card > .elementor-widget-wrap { padding: 18px; }
  selector .arc-search-field input, selector .arc-search-field select { font-size: 16px; padding-inline: 8px; }
}

/* The existing renderer supplies every room, permalink and starting rate. */
selector { background: #FFFFFF; }
selector .elementor-widget { margin-bottom: 0; }
selector .elementor-widget-wrap { flex-direction: column; gap: 16px; }
selector .arc-archive-grid-eyebrow .elementor-heading-title { color: var(--arc-brand-teal, #0A74A6); }
selector .arc-archive-grid-title .elementor-heading-title { color: var(--arc-brand-navy, #082465); }
selector .arc-archive-grid-copy { max-width: 700px; color: var(--arc-brand-navy, #082465); }
selector .elementor-widget-text-editor p { margin: 0; }
selector .arc-rooms-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 28px; width: 100%; margin: 16px 0 0; }
selector .arc-room-card {
  display: flex;
  flex-direction: column;
  min-width: 0;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: 1px solid rgba(var(--arc-brand-navy-rgb, 8, 36, 101), .12);
  border-radius: 0;
  background: #FFFFFF;
  box-shadow: 0 5px 20px rgba(var(--arc-brand-navy-rgb, 8, 36, 101), .04);
  transition: border-color .2s ease, box-shadow .2s ease;
}
selector .arc-room-card:hover { border-color: var(--arc-brand-cyan, #1B9EC2); box-shadow: 0 12px 32px rgba(var(--arc-brand-navy-rgb, 8, 36, 101), .10); }
selector .arc-room-thumb { position: relative; flex-shrink: 0; width: 100%; height: auto; aspect-ratio: 4 / 3; overflow: hidden; }
selector .arc-room-thumb a { display: block; width: 100%; height: 100%; }
selector .arc-room-thumb img { display: block; width: 100%; max-width: 100%; height: 100%; object-fit: cover; object-position: center; border-radius: 0; transition: transform .5s ease; }
selector .arc-room-card:hover .arc-room-thumb img { transform: scale(1.035); }
/* The renderer's badge has inline colors; only its presentation is overridden. */
selector .arc-room-badge { background: var(--arc-brand-navy, #082465) !important; color: #FFFFFF !important; border-radius: 0 !important; font-family: Inter, Arial, sans-serif; }
selector .arc-room-details { display: flex; flex: 1 1 auto; flex-direction: column; gap: 14px; min-width: 0; padding: 23px; }
selector .arc-room-title { margin: 0; font-family: 'Playfair Display', Georgia, serif; font-size: 25px; font-weight: 600; line-height: 1.25; }
selector .arc-room-title a { color: var(--arc-brand-navy, #082465); text-decoration: none; overflow-wrap: anywhere; }
selector .arc-room-title a:hover { color: var(--arc-brand-teal, #0A74A6); }
selector .arc-room-capacity { display: flex; flex-wrap: wrap; gap: 4px 8px; margin: 0; color: var(--arc-brand-navy, #082465); font-family: Inter, Arial, sans-serif; font-size: 12px; line-height: 1.7; }
selector .arc-room-amenities { display: flex; flex-wrap: wrap; gap: 6px; margin: 0; }
selector .arc-amenity-pill { display: inline-flex; max-width: 100%; margin: 0; padding: 5px 8px; border: 1px solid rgba(var(--arc-brand-teal-rgb, 10, 116, 166), .18); border-radius: 0; background: var(--arc-brand-tint, #F0F8FB); color: var(--arc-brand-navy, #082465); font-family: Inter, Arial, sans-serif; font-size: 11px; line-height: 1.5; overflow-wrap: anywhere; }
selector .arc-room-footer { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px; margin-top: auto; padding-top: 18px; border-top: 1px solid rgba(var(--arc-brand-navy-rgb, 8, 36, 101), .12); }
selector .arc-room-price { min-width: 0; color: var(--arc-brand-navy, #082465); }
selector .arc-from, selector .arc-per-night { color: var(--arc-brand-teal, #0A74A6); font-family: Inter, Arial, sans-serif; font-size: 11px; line-height: 1.5; }
selector .arc-price-amount { display: block; color: var(--arc-brand-navy, #082465); font-family: 'Playfair Display', Georgia, serif; font-size: 26px; font-weight: 600; line-height: 1.25; overflow-wrap: anywhere; }
selector .arc-room-footer .arc-btn-primary { display: inline-flex; align-items: center; justify-content: center; min-height: 44px; max-width: 100%; padding: 12px 15px; border: 1px solid var(--arc-brand-orange, #F48C06); border-radius: 0; background: var(--arc-brand-orange, #F48C06); color: var(--arc-brand-navy, #082465); font-family: Inter, Arial, sans-serif; font-size: 13px; font-weight: 600; line-height: 1.5; text-decoration: none; white-space: normal; }
selector .arc-room-footer .arc-btn-primary:hover { border-color: var(--arc-brand-orange-hover, #D97706); background: var(--arc-brand-orange-hover, #D97706); color: var(--arc-brand-navy, #082465); }
selector a:focus-visible { outline: 2px solid var(--arc-brand-teal, #0A74A6); outline-offset: 3px; }
selector .arc-no-rooms { padding: 24px; border: 1px solid rgba(var(--arc-brand-teal-rgb, 10, 116, 166), .18); background: var(--arc-brand-tint, #F0F8FB); color: var(--arc-brand-navy, #082465); }
@media (max-width: 1024px) { selector .arc-rooms-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 22px; } }
@media (max-width: 767px) { selector .arc-rooms-grid { grid-template-columns: minmax(0, 1fr); gap: 22px; } selector .arc-room-details { padding: 20px; } }
@media (prefers-reduced-motion: reduce) { selector .arc-room-card, selector .arc-room-thumb img { transition: none; } selector .arc-room-card:hover .arc-room-thumb img { transform: none; } }

selector { background: var(--arc-brand-tint, #F0F8FB); }
selector .elementor-widget { margin-bottom: 0; }
selector > .elementor-container > .elementor-column > .elementor-widget-wrap { flex-direction: column; gap: 16px; }
selector .arc-archive-policies-title .elementor-heading-title { color: var(--arc-brand-navy, #082465); }
selector .arc-archive-policies-copy { color: var(--arc-brand-navy, #082465); }
selector .elementor-widget-text-editor p { margin: 0; }
selector .arc-archive-policies-grid { margin-top: 14px; }
selector .arc-archive-policies-grid > .elementor-container { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 20px; width: 100%; max-width: none; }
selector .arc-archive-policy-card { width: 100% !important; min-width: 0; }
selector .arc-archive-policy-card > .elementor-widget-wrap { display: flex; align-content: flex-start; padding: 28px 20px; border: 1px solid rgba(var(--arc-brand-teal-rgb, 10, 116, 166), .15); border-radius: 12px; background: #FFFFFF; }
selector .arc-archive-policy-card .elementor-widget { width: 100%; }
selector .elementor-icon { color: var(--arc-brand-teal, #0A74A6); }
selector .elementor-icon svg { fill: var(--arc-brand-teal, #0A74A6); }
selector .elementor-icon-box-title, selector .elementor-icon-box-description { color: var(--arc-brand-navy, #082465); }
selector .elementor-icon-box-description strong { display: inline-block; margin-bottom: 4px; font-size: 20px; font-weight: 600; }
@media (max-width: 1024px) { selector .arc-archive-policies-grid > .elementor-container { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 767px) { selector .arc-archive-policies-grid > .elementor-container { grid-template-columns: minmax(0, 1fr); gap: 16px; } }
